// OctoechosToneFull holds complete hymnography for a tone
type OctoechosToneFull struct {
	ToneNumber         int
	ToneName           string
	Apolytikion        string
	Theotokion         string
	Hypakoe            string
	Kontakion          string
	Kathisma1          string
	Kathisma2          string
	Anavathmoi         string
	ProkeimenonMatins  string
	ProkeimMatinsStich string
	KekragariaStichera []string
	ApostichaVespers   []string
	AinoiStichera      []string
	ApostichaMatins    []string
}

// EothinonRecord holds the 11 Sunday Resurrection Gospels & Doxastika
