// GetEothinonNumber returns the Eothinon number (1-11) for a given date
func GetEothinonNumber(date time.Time) int {
	easter := CalculateOrthodoxEaster(date.Year())
	// Days since Pentecost (Easter + 50 days)
	pentecost := easter.AddDate(0, 0, 50)
	diffDays := int(date.Sub(pentecost).Hours() / 24)
	if diffDays < 0 {
		diffDays += 365
	}
	weeks := diffDays / 7
	eoth := (weeks % 11) + 1
	if eoth <= 0 || eoth > 11 {
		eoth = 1
	}
	return eoth
}

